import os
import google.generativeai as genai

def moderate_text(payload, config=None):
    config = config or {}
    genai.configure(api_key=os.environ["GEMINI_API_KEY"])
    model = genai.GenerativeModel('gemini-1.5-flash-latest')
    response = model.generate_content(
        contents=[payload],
        safety_settings={
            "HARM_CATEGORY_HARASSMENT": "BLOCK_NONE",
            "HARM_CATEGORY_HATE_SPEECH": "BLOCK_NONE",
            "HARM_CATEGORY_SEXUALLY_EXPLICIT": "BLOCK_NONE",
            "HARM_CATEGORY_DANGEROUS_CONTENT": "BLOCK_NONE",
        }
    )

    # Gemini's safety feedback is structured as a list of "safety_ratings"
    # where each rating corresponds to a HARM_CATEGORY.
    # We need to transform this into a more generic "result" format
    # which indicates if *any* category was blocked.
    # If the response was blocked entirely, access to response.candidates will raise an exception.
    # In such cases, we assume it was blocked for safety reasons.

    blocked_categories = []

    try:
        if not response.candidates:
            # If there are no candidates, it means the content was blocked.
            # We iterate through the prompt_feedback to find out why.
            for rating in response.prompt_feedback.safety_ratings:
                if rating.blocked:
                    blocked_categories.append(rating.category.name.replace("HARM_CATEGORY_", ""))

            result = {
                "flagged": len(blocked_categories) > 0,
                "categories": blocked_categories
            }
        else:
            # If candidates exist, it means the content was not blocked
            result = {
                "flagged": False,
                "categories": []
            }

    except Exception as e:
        # Catch cases where response.candidates might be inaccessible due to blocking
        # This typically happens if *any* category reached a blocking threshold.
        # We try to extract info from prompt_feedback if available.
        if hasattr(response, 'prompt_feedback') and response.prompt_feedback:
            for rating in response.prompt_feedback.safety_ratings:
                if rating.blocked:
                    blocked_categories.append(rating.category.name.replace("HARM_CATEGORY_", ""))
            result = {
                "flagged": len(blocked_categories) > 0,
                "categories": blocked_categories
            }
        else:
            # Fallback if no specific feedback is available but an exception occurred
            result = {
                "flagged": True, # Assume flagged if an error prevented normal processing
                "categories": ["UNKNOWN_BLOCKED"]
            }

    return result
